import{d as c,C as t,o as b,c as u,j as a,a as s,E as o,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第五十章","description":"循王弼十分有三与不以欲累身的解释，理解生生之厚、善摄生和无死地。","frontmatter":{"title":"道德经第五十章","description":"循王弼十分有三与不以欲累身的解释，理解生生之厚、善摄生和无死地。","category":"guide","aliases":["道德经第五十章","老子第五十章","dao de jing chapter 50"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-50.md","filePath":"daoism/dao-de-jing/chapter-50.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-50.md"},_=c({...m,setup(p){const i=[{id:"emerging-into-life",label:"出生入死",showLabel:!0,sentences:[["出生入死。"]],note:["【白话】出而进入生的境地，入而进入死的境地。开篇先把生命的生与死并举，为下文不同趋向作起点。","【王弼注择要】「出生地，入死地。」注以生地、死地解释出入，不先按现代成语的英勇冒险来读。","【读法】这一句的出入说法简约，本页沿王注作生死之境解释，须连下文的生道、死道与动入死地一起看。"]},{id:"three-tenths",label:"生之徒十有三",showLabel:!0,sentences:[["生之",{text:"徒",glossary:"tu"},{text:"十有三",glossary:"shiyousan"},"，死之",{text:"徒",glossary:"tu"},{text:"十有三",glossary:"shiyousan"},"，人之生动之",{text:"死地",glossary:"sidi"},"，亦",{text:"十有三",glossary:"shiyousan"},"。"]],note:["【白话】属于生道的，说有十分之三；属于死道的，说有十分之三；人本求生，行动却趋入死地的，也说有十分之三。这一组数字在本页依王弼解释。","【王弼注择要】「十有三，犹云十分有三。」注继而分别说取生道、取死道，又把生生之厚连到转入无生之地。","【读法】本页不作十三解，也不把三组数字当作经实际调查得出的死亡统计。人之生动之死地沿求生而动入死地理解，正文原有标点不改；所据录文此句未见本站的亦字。"]},{id:"excessive-pursuit-of-life",label:"以其生生之厚",showLabel:!0,sentences:[["夫何故？以其",{text:"生生",glossary:"shengsheng"},"之",{text:"厚",glossary:"hou"},"。"]],note:["【白话】为什么会这样？因为把求生、厚养生命看得过重，反而使自己的行动走向伤生之处。","【王弼注择要】注后文以鸟兽本处在难以捕取之地、却终因甘饵受诱来反问「岂非生生之厚乎」，说明求得更多养生条件也可能使自己离本涉险。","【读法】生生在此取营求、保养生命之意，厚指过厚。批评的是求生之欲反过来牵累自身，不是否定正常饮食、照料、医疗与自我保护。"]},{id:"good-care-of-life",label:"善摄生者",showLabel:!0,sentences:[["盖闻善",{text:"摄生",glossary:"shesheng"},"者，陆行不遇",{text:"兕",glossary:"si"},"虎，入军不",{text:"被",glossary:"bei"},{text:"甲兵",glossary:"jiabing"},"。"]],note:["【白话】听说善于保养、持守生命的人，陆地行走不遇兕虎之害，进入军阵也不受甲兵之伤。这里用极强的形象写善摄生者不自取伤生之处。","【王弼注择要】「善摄生者，无以生为生，故无死地也。」注以不执求生来求生说明善摄生，而非补入某种护身技术。","【读法】摄为保养、持守；兕是古代所称似犀的兽，具体物种不强定。被在本页取遭受义，结合后注入军而不害理解，不解作必须放弃盔甲与防护。"]},{id:"no-place-for-harm",label:"兕无所投其角",showLabel:!0,sentences:[[{text:"兕",glossary:"si"},"无所投其角，虎无所",{text:"措",glossary:"cuo"},"其爪，",{text:"兵",glossary:"bing"},"无所容其刃。"]],note:["【白话】兕找不到可以抵入其角的地方，虎找不到可以施下其爪的地方，兵器也找不到可以容入其刃的地方。三句铺陈伤害无处施加的形象。","【王弼注择要】「斯诚不以欲累其身者也，何死地之有乎？」注将前面的形象归到不被欲求牵累其身。","【读法】措为放置、施下，兵在此是兵器。无所施害是本章极写的成效，不能据此推断身体可免疫刀兵或猛兽；实际处境仍须避险、保护和求助。"]},{id:"not-making-a-place-for-death",label:"以其无死地",showLabel:!0,sentences:[["夫何故？以其无",{text:"死地",glossary:"sidi"},"。"]],note:["【白话】为什么会这样？因为他不因欲求而使自己落入伤生取死的境地。这是本页依王注对无死地的解释。","【王弼注择要】「不以求离其本，不以欲渝其真。」王弼以不为求欲而离本、变真收束，并连到虽入军而不害的经文形象。","【读法】两次夫何故分别追问生生之厚与善摄生。无死地不是许诺长生不死，也不能倒过来用死亡或伤害证明受害者必曾失道；本章讨论的是欲求与自取险境的关系。"]}],r=[{id:"tu",term:"徒",sense:1},{id:"shiyousan",term:"十有三",sense:1},{id:"sidi",term:"死地",sense:1},{id:"shengsheng",term:"生生",sense:1},{id:"hou",term:"厚",sense:1},{id:"shesheng",term:"摄生",sense:1},{id:"si",term:"兕",sense:1},{id:"bei",term:"被",sense:1},{id:"jiabing",term:"甲兵",sense:1},{id:"cuo",term:"措",sense:1},{id:"bing",term:"兵",sense:1}];return(x,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return b(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十章",tabindex:"-1"},[s("道德经第五十章 "),a("a",{class:"header-anchor",href:"#道德经第五十章","aria-label":'Permalink to "道德经第五十章"'},"​")],-1)),o(n,{title:"越想厚养生命，为什么反而可能走向死地",summary:"本章先列生、死与动入死地的三种情形，再追问生生之厚，最后以兕虎、兵刃无所施害的形象说善摄生。王弼把十有三释为十分有三，并以不以欲累身、不离其本解释无死地。",points:[{label:"先读",text:"出生入死按出入生死之境读，不直接套现代成语舍生冒险的意思。"},{label:"再辨",text:"十有三循王弼作十分之三，生生之厚反省求生过厚而反伤生命。"},{label:"后看",text:"兕虎、甲兵的形象说不以欲累身，不可据此许诺免受现实伤害。"}],hint:"兕读 sì，摄读 shè，措读 cuò；十有三在本页循王弼读作十分有三，被甲兵的被暂取遭受义，读 bèi。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"夫何故？以其生生之厚。",tone:"求生过厚的反转",guide:"连下文甘饵诱取的王注看，所忧在为求欲而离本涉险。"},{text:"兕无所投其角，虎无所措其爪，兵无所容其刃。",tone:"伤害无所施的形象",guide:"依不以欲累身理解，不把形象当作现实免伤保证。"},{text:"夫何故？以其无死地。",tone:"两次追问的收束",guide:"从求生而反伤身，转到不因欲求自入险境，辨清无死地的读法。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=g("",15))])}}});export{y as __pageData,_ as default};
